package org.slavicmyths.rpg;
import java.util.*;
import net.minecraft.network.chat.Component;
/** Existing rune parameters shared by gameplay, anvil and rune-item tooltips. */
public record RuneDefinition(String id,Map<String,Double> parameters,Set<String> categories) {
 public static final Map<String,RuneDefinition> ALL=new LinkedHashMap<>();
 static {for(var d:List.of(new RuneDefinition("thunder",Map.ofEntries(Map.entry("hit_cooldown",140.0),Map.entry("heavy_damage",2.0),Map.entry("dagger_damage",1.0),Map.entry("hit_damage",1.5),Map.entry("chain_radius",2.0),Map.entry("chain_damage",1.0),Map.entry("shield_cooldown",180.0),Map.entry("shield_damage",1.5),Map.entry("staff_bonus",1.15)),Set.of("sword","dagger","spear","heavy","bow","shield","staff")),new RuneDefinition("heat",Map.ofEntries(Map.entry("hit_cooldown",180.0),Map.entry("fire_seconds",2.0),Map.entry("shield_cooldown",200.0),Map.entry("shield_fire_seconds",1.0),Map.entry("staff_cooldown",200.0),Map.entry("staff_fire_seconds",2.0)),Set.of("sword","dagger","spear","heavy","bow","shield","staff")),new RuneDefinition("forest",Map.ofEntries(Map.entry("melee_damage",1.0),Map.entry("shield_cooldown",240.0),Map.entry("shield_duration",60.0),Map.entry("shield_level",0.0),Map.entry("staff_cooldown",600.0),Map.entry("staff_regeneration",80.0),Map.entry("staff_level",0.0),Map.entry("arrow_speed",0.08)),Set.of("sword","dagger","spear","heavy","bow","shield","staff")),new RuneDefinition("midday",Map.ofEntries(Map.entry("melee_damage",1.0),Map.entry("shield_cooldown",240.0),Map.entry("shield_duration",40.0),Map.entry("shield_level",0.0),Map.entry("bow_multiplier",1.12),Map.entry("staff_cooldown",0.9)),Set.of("sword","dagger","spear","heavy","bow","shield","staff")),new RuneDefinition("shadow",Map.ofEntries(Map.entry("light_threshold",7.0),Map.entry("staff_cooldown",0.9),Map.entry("dagger_damage",1.25),Map.entry("speed_cooldown",200.0),Map.entry("speed_duration",60.0),Map.entry("speed_level",0.0),Map.entry("bow_multiplier",1.1)),Set.of("sword","dagger","bow","staff")),new RuneDefinition("protection",Map.ofEntries(Map.entry("hit_cooldown",300.0),Map.entry("hit_duration",40.0),Map.entry("hit_level",0.0),Map.entry("shield_cooldown",240.0),Map.entry("shield_duration",60.0),Map.entry("shield_level",0.0),Map.entry("staff_cooldown",300.0),Map.entry("staff_duration",40.0),Map.entry("staff_level",0.0)),Set.of("sword","dagger","spear","heavy","bow","shield","staff")),new RuneDefinition("wind",Map.ofEntries(Map.entry("hit_cooldown",140.0),Map.entry("spear_force",0.45),Map.entry("weapon_force",0.25),Map.entry("shield_cooldown",160.0),Map.entry("shield_force",0.4),Map.entry("staff_cooldown",160.0),Map.entry("staff_force",0.5),Map.entry("arrow_speed",0.08)),Set.of("sword","dagger","spear","heavy","bow","shield","staff")),new RuneDefinition("life",Map.ofEntries(Map.entry("shield_health_threshold",0.5),Map.entry("shield_cooldown",600.0),Map.entry("shield_regeneration",80.0),Map.entry("shield_level",0.0),Map.entry("staff_cooldown",900.0),Map.entry("staff_healing",2.0),Map.entry("kill_cooldown",800.0),Map.entry("kill_healing",3.0)),Set.of("sword","dagger","spear","heavy","bow","shield","staff"))))ALL.put(d.id,d);}
 static {for(String id:AdvancedRuneRules.IDS)ALL.put(id,new RuneDefinition(id,Map.of(),Set.of()));}
 static {ALL.put("earth_lord_iv",new RuneDefinition("earth_lord_iv",Map.of(),Set.of("sword","dagger","spear","heavy","whip")));}
 static {ALL.put("waning",new RuneDefinition("waning",Map.of(),Set.of("sword","dagger","spear","heavy","staff","bow","whip")));ALL.put("frost_resistance",new RuneDefinition("frost_resistance",Map.of(),Set.of()));ALL.put("frost",new RuneDefinition("frost",Map.of(),Set.of("sword","dagger","spear","heavy","staff","bow","whip")));}
 public static double n(String id,String key){return ALL.get(id).parameters.get(key);}
 public static int i(String id,String key){return (int)n(id,key);}
 public static float f(String id,String key){return (float)n(id,key);}
 private static String format(double n){return java.math.BigDecimal.valueOf(n).setScale(3,java.math.RoundingMode.HALF_UP).stripTrailingZeros().toPlainString();}
 public Component name(){if(id.equals("waning"))return Component.translatable("item.slavicmyths.rune_of_waning");if(id.startsWith("frost"))return Component.translatable("item.slavicmyths."+(id.equals("frost")?"frost_rune":"frost_resistance_rune"));return org.slavicmyths.industry.MiningRunes.mining(id)?org.slavicmyths.industry.MiningRunes.name(id):Component.translatable("item.slavicmyths.rune_"+id);}
 private String v(String key){return format(parameters.get(key));}
 private String sec(String key){return format(parameters.get(key)/20);}
 private String pct(String key){return format(parameters.get(key)*100);}
 private String bonus(String key){return format((parameters.get(key)-1)*100);}
 private String discount(String key){return format((1-parameters.get(key))*100);}
 private Object[] effectArguments(){return switch(id){
  case "thunder"->new Object[]{v("hit_damage"),v("heavy_damage"),v("dagger_damage"),sec("hit_cooldown"),v("chain_damage"),v("chain_radius"),v("shield_damage"),sec("shield_cooldown"),bonus("staff_bonus")};
  case "heat"->new Object[]{v("fire_seconds"),sec("hit_cooldown"),v("shield_fire_seconds"),sec("shield_cooldown"),v("staff_fire_seconds"),sec("staff_cooldown")};
  case "forest"->new Object[]{v("melee_damage"),pct("arrow_speed"),sec("shield_duration"),sec("shield_cooldown"),sec("staff_regeneration"),sec("staff_cooldown")};
  case "midday"->new Object[]{v("melee_damage"),bonus("bow_multiplier"),sec("shield_duration"),sec("shield_cooldown"),discount("staff_cooldown")};
  case "shadow"->new Object[]{v("light_threshold"),v("dagger_damage"),sec("speed_duration"),sec("speed_cooldown"),bonus("bow_multiplier"),discount("staff_cooldown")};
  case "protection"->new Object[]{sec("hit_duration"),sec("hit_cooldown"),sec("shield_duration"),sec("shield_cooldown")};
  case "life"->new Object[]{v("kill_healing"),sec("kill_cooldown"),pct("shield_health_threshold"),sec("shield_regeneration"),sec("shield_cooldown"),v("staff_healing"),sec("staff_cooldown")};
  case "wind"->new Object[]{v("weapon_force"),v("spear_force"),sec("hit_cooldown"),v("shield_force"),sec("shield_cooldown"),v("staff_force"),sec("staff_cooldown"),pct("arrow_speed")};
  default->new Object[0];};
 }
 static {ALL.put("mor_breath",new RuneDefinition("mor_breath",Map.of(),Set.of("sword","dagger","spear","heavy","staff","whip")));ALL.put("dragon_flame",new RuneDefinition("dragon_flame",Map.of(),Set.of("sword","dagger","spear","heavy","whip")));ALL.put("storm_strike",new RuneDefinition("storm_strike",Map.of(),Set.of("bow")));}
 public Component legacyEffect(){if(org.slavicmyths.gorynych.GorynychContent.RUNES.contains(id))return Component.translatable("item.slavicmyths.rune_"+id+".desc");if(org.slavicmyths.rewards.RewardContent.RUNES.contains(id))return Component.translatable("item.slavicmyths.rune_"+id+".desc");return org.slavicmyths.industry.MiningRunes.mining(id)?Component.translatable("industry.slavicmyths.hint."+org.slavicmyths.industry.MiningRunes.itemId(id)):Component.translatable("rpg.slavicmyths.effect_"+id,effectArguments());}
 public Component effect(){if(AdvancedRunes.newRune(id))return AdvancedRunes.description(id);if(id.equals("waning"))return Component.translatable("item.slavicmyths.rune_of_waning.desc");if(id.startsWith("frost"))return Component.translatable("item.slavicmyths."+(id.equals("frost")?"frost_rune":"frost_resistance_rune")+".desc");if(RareRunes.rare(id))return RareRunes.text("effect_"+id);if(!RuneBalance.modern(id))return legacyEffect();var text=Component.empty();for(var c:RuneRework.effects(id,1,null)){if(!text.getString().isEmpty())text.append("; ");text.append(c);}return text;}
 public List<Component> tooltip(){if(AdvancedRunes.newRune(id))return List.of(effect(),compatible());if(org.slavicmyths.gorynych.GorynychContent.RUNES.contains(id))return List.of(legacyEffect(),Component.translatable("gorynych196.compatible_"+id));if(id.equals("waning"))return List.of(effect(),compatible());if(id.startsWith("frost"))return List.of(effect(),Component.translatable("frost191.compatible."+id));if(org.slavicmyths.rewards.RewardContent.RUNES.contains(id))return List.of(legacyEffect(),compatible());if(id.equals("earth_heart_iii"))return org.slavicmyths.earth.EarthRune.tooltip();if(org.slavicmyths.industry.MiningRunes.mining(id))return org.slavicmyths.industry.MiningRunes.tooltip(id);if(RareRunes.rare(id))return RareRunes.tooltip(id);return RuneBalance.modern(id)?RuneRework.runeTooltip(id):java.util.stream.IntStream.rangeClosed(1,3).mapToObj(i->(Component)Component.translatable("rpg.slavicmyths.rune_hint_"+id+"_"+i,effectArguments())).toList();}
 public Component compatible(){if(AdvancedRunes.newRune(id))return Component.translatable("runes_patch.compatible."+id);if(org.slavicmyths.gorynych.GorynychContent.RUNES.contains(id))return Component.translatable("gorynych196.compatible_"+id);if(id.equals("waning"))return Component.translatable("night192.compatible.waning");if(id.startsWith("frost"))return Component.translatable("frost191.compatible."+id);if(org.slavicmyths.rewards.RewardContent.RUNES.contains(id))return Component.translatable("reward176.compatible."+id);if(org.slavicmyths.industry.MiningRunes.mining(id))return Component.translatable("industry.slavicmyths.pickaxe_only");if(RareRunes.rare(id))return RareRunes.compatibility(id);if(RuneBalance.modern(id))return RuneRework.compatibility(id);var names=categories.stream().sorted().map(c->Component.translatable("rpg.slavicmyths.category_"+c)).toList();var text=Component.empty();for(var c:names){if(!text.getString().isEmpty())text.append(", ");text.append(c);}return Component.translatable("rpg.slavicmyths.compatible",text);}
 static {for(var d:RuneBalance.DEFINITIONS)if(!ALL.containsKey(d.id()))ALL.put(d.id(),new RuneDefinition(d.id(),Map.of(),Set.of()));}
 static {for(String id:RareRuneRules.IDS)ALL.put(id,new RuneDefinition(id,Map.of(),Set.of()));}
 static {for(String id:List.of("stomp","dispelling","pursuit","suppression","battle_line"))ALL.put(id,new RuneDefinition(id,Map.of(),Set.of()));}
}
